// Art for the game, generated by Gemini into src/assets/ (see tools/gen-asset.mjs).
//
// - preloadArt(): await once at boot, before the first frame.
// - art(name): the loaded image for src/assets/<name>.webp (or .png), or null.
//   Draw code must handle null with its own Canvas fallback, so the game still
//   runs when an asset is missing or Google AI was not available.
//
// Vite inlines every file matched here into dist/index.html, so keep only
// assets the game uses in src/assets/ (raw PNGs live in tools/art-src/).

const files = import.meta.glob('./assets/*.{webp,png}', {
  eager: true,
  import: 'default',
}) as Record<string, string>;

const images = new Map<string, HTMLImageElement>();

function keyOf(path: string): string {
  return path.replace(/^.*\//, '').replace(/\.(webp|png)$/, '');
}

export function preloadArt(): Promise<void> {
  const jobs = Object.entries(files).map(
    ([path, url]) =>
      new Promise<void>((resolve) => {
        const img = new Image();
        img.onload = () => {
          const key = keyOf(path);
          if (!images.has(key) || path.endsWith('.webp')) images.set(key, img);
          resolve();
        };
        img.onerror = () => resolve();
        img.src = url;
      }),
  );
  return Promise.all(jobs).then(() => undefined);
}

export function art(name: string): HTMLImageElement | null {
  return images.get(name) ?? null;
}
